// swift-tools-version: 6.1
import PackageDescription

let package = Package(
    name: "kvhttp",
    platforms: [.macOS(.v15)],
    products: [.executable(name: "app", targets: ["app"])],
    targets: [
        .target(name: "KVHTTP", swiftSettings: [.enableUpcomingFeature("ExistentialAny")]),
        .executableTarget(name: "app", dependencies: ["KVHTTP"]),
        .testTarget(name: "KVHTTPTests", dependencies: ["KVHTTP"]),
    ]
)

import Foundation

public struct HTTPStatus: Sendable, Equatable, CustomStringConvertible {
    public let code: Int
    public let reason: String

    public var description: String { "\(code) \(reason)" }

    public static let ok = HTTPStatus(code: 200, reason: "OK")
    public static let created = HTTPStatus(code: 201, reason: "Created")
    public static let noContent = HTTPStatus(code: 204, reason: "No Content")
    public static let badRequest = HTTPStatus(code: 400, reason: "Bad Request")
    public static let notFound = HTTPStatus(code: 404, reason: "Not Found")
    public static let methodNotAllowed = HTTPStatus(code: 405, reason: "Method Not Allowed")
    public static let payloadTooLarge = HTTPStatus(code: 413, reason: "Content Too Large")
    public static let headersTooLarge = HTTPStatus(code: 431, reason: "Request Header Fields Too Large")
    public static let notImplemented = HTTPStatus(code: 501, reason: "Not Implemented")
    public static let versionNotSupported = HTTPStatus(code: 505, reason: "HTTP Version Not Supported")
}

public struct HTTPRequest: Sendable, Equatable {
    public var method: String
    public var path: String
    public var headers: [(name: String, value: String)]
    public var body: [UInt8]
    /// Whether the client wants the connection kept open after the response.
    public var keepAlive: Bool

    public init(method: String, path: String, headers: [(name: String, value: String)] = [], body: [UInt8] = [], keepAlive: Bool = false) {
        self.method = method
        self.path = path
        self.headers = headers
        self.body = body
        self.keepAlive = keepAlive
    }

    public static func == (lhs: HTTPRequest, rhs: HTTPRequest) -> Bool {
        lhs.method == rhs.method && lhs.path == rhs.path && lhs.body == rhs.body && lhs.keepAlive == rhs.keepAlive
            && lhs.headers.elementsEqual(rhs.headers) { $0.name == $1.name && $0.value == $1.value }
    }
}

public struct HTTPResponse: Sendable, Equatable {
    public var status: HTTPStatus
    public var contentType: String?
    public var body: [UInt8]

    public init(status: HTTPStatus, contentType: String? = nil, body: [UInt8] = []) {
        self.status = status
        self.contentType = contentType
        self.body = body
    }

    public static func text(_ status: HTTPStatus, _ text: String) -> HTTPResponse {
        HTTPResponse(status: status, contentType: "text/plain; charset=utf-8", body: Array(text.utf8))
    }

    public static func error(_ status: HTTPStatus) -> HTTPResponse {
        .text(status, status.reason.lowercased())
    }

    /// The full HTTP/1.1 wire representation of this response.
    /// - Parameter includeBody: `false` for responses to `HEAD`, which carry headers only.
    public func serialized(keepAlive: Bool, includeBody: Bool = true) -> Data {
        var head = "HTTP/1.1 \(status.code) \(status.reason)\r\n"
        if let contentType {
            head += "Content-Type: \(contentType)\r\n"
        }
        head += "Content-Length: \(body.count)\r\n"
        head += "Connection: \(keepAlive ? "keep-alive" : "close")\r\n\r\n"

        var data = Data(capacity: head.utf8.count + body.count)
        data.append(contentsOf: head.utf8)
        if includeBody {
            data.append(contentsOf: body)
        }
        return data
    }
}

/// Incremental HTTP/1.x request parser. Feed bytes with ``append(_:)`` and pull
/// complete requests with ``next()``; leftover bytes are kept for pipelined requests.
public struct HTTPRequestParser: Sendable {
    public enum Result: Sendable, Equatable {
        case incomplete
        case request(HTTPRequest)
        /// The request is malformed or unacceptable; respond with the status and close.
        case failure(HTTPStatus)
    }

    private struct Head: Sendable {
        var method: String
        var path: String
        var headers: [(name: String, value: String)]
        var contentLength: Int
        var keepAlive: Bool
    }

    public let maxHeaderBytes: Int
    public let maxBodyBytes: Int

    private var buffer: [UInt8] = []
    /// Offset up to which `buffer` has been searched for the end of the header block.
    private var scannedOffset = 0
    /// A parsed head whose body has not fully arrived yet.
    private var pendingHead: Head?
    private var pendingBodyStart = 0

    public init(maxHeaderBytes: Int = 64 * 1024, maxBodyBytes: Int) {
        self.maxHeaderBytes = maxHeaderBytes
        self.maxBodyBytes = maxBodyBytes
    }

    public mutating func append(_ bytes: some Sequence<UInt8>) {
        buffer.append(contentsOf: bytes)
    }

    public mutating func next() -> Result {
        if pendingHead == nil {
            guard let headerEnd = findHeaderTerminator() else {
                return buffer.count > maxHeaderBytes ? .failure(.headersTooLarge) : .incomplete
            }
            switch Self.parseHead(buffer[..<headerEnd], maxBodyBytes: maxBodyBytes) {
            case .success(let head):
                pendingHead = head
                pendingBodyStart = headerEnd + 4
            case .failure(let status):
                return .failure(status)
            }
        }

        guard let head = pendingHead else { return .incomplete }
        let bodyEnd = pendingBodyStart + head.contentLength
        guard buffer.count >= bodyEnd else { return .incomplete }

        let request = HTTPRequest(
            method: head.method,
            path: head.path,
            headers: head.headers,
            body: Array(buffer[pendingBodyStart..<bodyEnd]),
            keepAlive: head.keepAlive
        )
        buffer.removeFirst(bodyEnd)
        pendingHead = nil
        scannedOffset = 0
        return .request(request)
    }

    /// Index of the `\r\n\r\n` that ends the header block, if present.
    private mutating func findHeaderTerminator() -> Int? {
        let cr = UInt8(ascii: "\r"), lf = UInt8(ascii: "\n")
        var index = max(0, scannedOffset - 3)
        while index + 3 < buffer.count {
            if buffer[index] == cr, buffer[index + 1] == lf, buffer[index + 2] == cr, buffer[index + 3] == lf {
                return index
            }
            index += 1
        }
        scannedOffset = buffer.count
        return nil
    }

    private enum HeadResult {
        case success(Head)
        case failure(HTTPStatus)
    }

    private static func parseHead(_ bytes: ArraySlice<UInt8>, maxBodyBytes: Int) -> HeadResult {
        let text = String(decoding: bytes, as: UTF8.self)
        var lines = text.split(separator: "\r\n", omittingEmptySubsequences: false)[...]
        guard let requestLine = lines.popFirst() else { return .failure(.badRequest) }

        let parts = requestLine.split(separator: " ", omittingEmptySubsequences: false)
        guard parts.count == 3, !parts[0].isEmpty, parts[1].hasPrefix("/") else { return .failure(.badRequest) }
        let method = String(parts[0]), path = String(parts[1]), version = parts[2]
        guard version.hasPrefix("HTTP/") else { return .failure(.badRequest) }
        guard version == "HTTP/1.1" || version == "HTTP/1.0" else { return .failure(.versionNotSupported) }

        var headers: [(name: String, value: String)] = []
        var contentLength: Int?
        var connectionTokens: [Substring] = []

        for line in lines {
            guard let colon = line.firstIndex(of: ":") else { return .failure(.badRequest) }
            let name = line[..<colon]
            guard !name.isEmpty, !name.contains(where: \.isWhitespace) else { return .failure(.badRequest) }
            let value = line[line.index(after: colon)...].trimmingWhitespace()
            headers.append((String(name), String(value)))

            switch name.lowercased() {
            case "content-length":
                guard !value.isEmpty, value.utf8.allSatisfy({ (UInt8(ascii: "0")...UInt8(ascii: "9")).contains($0) }) else {
                    return .failure(.badRequest)
                }
                // Lengths beyond Int range are certainly too large.
                let length = Int(value) ?? Int.max
                if let contentLength, contentLength != length { return .failure(.badRequest) }
                contentLength = length
            case "transfer-encoding":
                return .failure(.notImplemented)
            case "connection":
                connectionTokens += value.lowercased().split(separator: ",").map { $0.trimmingWhitespace() }
            default:
                break
            }
        }

        let length = contentLength ?? 0
        guard length <= maxBodyBytes else { return .failure(.payloadTooLarge) }

        let keepAlive = version == "HTTP/1.1"
            ? !connectionTokens.contains("close")
            : connectionTokens.contains("keep-alive")

        return .success(Head(method: method, path: path, headers: headers, contentLength: length, keepAlive: keepAlive))
    }
}

extension Substring {
    fileprivate func trimmingWhitespace() -> Substring {
        let start = firstIndex { $0 != " " && $0 != "\t" } ?? endIndex
        let end = lastIndex { $0 != " " && $0 != "\t" }.map(index(after:)) ?? start
        return self[start..<end]
    }
}

import Synchronization

/// Thread-safe in-memory key-value store.
public final class KVStore: Sendable {
    public enum PutResult: Sendable, Equatable {
        case created
        case replaced
    }

    private let storage = Mutex<[String: [UInt8]]>([:])

    public init() {}

    @discardableResult
    public func put(_ key: String, value: [UInt8]) -> PutResult {
        storage.withLock { $0.updateValue(value, forKey: key) == nil ? .created : .replaced }
    }

    public func get(_ key: String) -> [UInt8]? {
        storage.withLock { $0[key] }
    }

    /// Returns `true` if the key existed.
    @discardableResult
    public func delete(_ key: String) -> Bool {
        storage.withLock { $0.removeValue(forKey: key) != nil }
    }

    public func sortedKeys() -> [String] {
        storage.withLock { Array($0.keys) }.sorted()
    }
}

import Foundation

/// Maps requests onto the key-value store. Contains no networking code.
public struct Router: Sendable {
    public static let maxValueSize = 1 << 20
    static let maxKeyLength = 64

    private let store: KVStore

    public init(store: KVStore) {
        self.store = store
    }

    public func respond(to request: HTTPRequest) -> HTTPResponse {
        let path = request.path
        switch path {
        case "/health":
            guard request.method == "GET" else { return .error(.methodNotAllowed) }
            return .text(.ok, "ok")

        case "/kv":
            guard request.method == "GET" else { return .error(.methodNotAllowed) }
            return listKeys()

        case _ where path.hasPrefix("/kv/"):
            let key = path.dropFirst("/kv/".count)
            guard Self.isValidKey(key) else { return .text(.badRequest, "invalid key") }
            return keyRoute(method: request.method, key: String(key), body: request.body)

        default:
            return .error(.notFound)
        }
    }

    private func keyRoute(method: String, key: String, body: [UInt8]) -> HTTPResponse {
        switch method {
        case "GET":
            guard let value = store.get(key) else { return .error(.notFound) }
            return HTTPResponse(status: .ok, contentType: "application/octet-stream", body: value)
        case "PUT":
            guard body.count <= Self.maxValueSize else { return .error(.payloadTooLarge) }
            return switch store.put(key, value: body) {
            case .created: HTTPResponse(status: .created)
            case .replaced: HTTPResponse(status: .ok)
            }
        case "DELETE":
            return store.delete(key) ? HTTPResponse(status: .noContent) : .error(.notFound)
        default:
            return .error(.methodNotAllowed)
        }
    }

    private func listKeys() -> HTTPResponse {
        let keys = store.sortedKeys()
        // Encoding an array of strings cannot fail.
        let json = (try? JSONEncoder().encode(keys)) ?? Data("[]".utf8)
        return HTTPResponse(status: .ok, contentType: "application/json", body: Array(json))
    }

    /// A key matches `[A-Za-z0-9_-]{1,64}`.
    static func isValidKey(_ key: some StringProtocol) -> Bool {
        let bytes = key.utf8
        guard (1...maxKeyLength).contains(bytes.count) else { return false }
        return bytes.allSatisfy { byte in
            switch byte {
            case UInt8(ascii: "A")...UInt8(ascii: "Z"),
                 UInt8(ascii: "a")...UInt8(ascii: "z"),
                 UInt8(ascii: "0")...UInt8(ascii: "9"),
                 UInt8(ascii: "_"), UInt8(ascii: "-"):
                true
            default:
                false
            }
        }
    }
}

import Foundation
import Network

/// HTTP/1.1 front end for ``Router`` built on Network.framework.
public final class Server: Sendable {
    public enum StartError: Error {
        case invalidPort(Int)
    }

    private let listener: NWListener
    private let router: Router
    private let queue = DispatchQueue(label: "kvhttp.listener")

    public init(host: String = "127.0.0.1", port: Int, store: KVStore = KVStore()) throws {
        guard let rawPort = UInt16(exactly: port), let endpointPort = NWEndpoint.Port(rawValue: rawPort), rawPort != 0 else {
            throw StartError.invalidPort(port)
        }
        let parameters = NWParameters.tcp
        parameters.allowLocalEndpointReuse = true
        parameters.requiredLocalEndpoint = .hostPort(host: NWEndpoint.Host(host), port: endpointPort)
        listener = try NWListener(using: parameters)
        listener.newConnectionLimit = NWListener.InfiniteConnectionLimit
        router = Router(store: store)
    }

    /// Starts accepting connections. `onFailure` is called if the listener fails (e.g. port in use).
    public func start(onFailure: @escaping @Sendable (NWError) -> Void) {
        listener.newConnectionHandler = { [router] connection in
            HTTPConnection(connection: connection, router: router).start()
        }
        listener.stateUpdateHandler = { state in
            if case .failed(let error) = state {
                onFailure(error)
            }
        }
        listener.start(queue: queue)
    }

    public func stop() {
        listener.cancel()
    }
}

/// Drives one client connection: read, parse, respond, repeat while keep-alive.
/// Parser state is threaded through the callbacks, so the type itself is immutable.
private struct HTTPConnection: Sendable {
    let connection: NWConnection
    let router: Router

    func start() {
        connection.stateUpdateHandler = { [connection] state in
            switch state {
            case .failed, .waiting:
                connection.cancel()
            default:
                break
            }
        }
        connection.start(queue: DispatchQueue(label: "kvhttp.connection"))
        receive(into: HTTPRequestParser(maxBodyBytes: Router.maxValueSize))
    }

    private func receive(into parser: HTTPRequestParser) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 1 << 18) { data, _, isComplete, error in
            var parser = parser
            if let data {
                parser.append(data)
            }
            process(parser, endOfInput: isComplete || error != nil)
        }
    }

    private func process(_ parser: HTTPRequestParser, endOfInput: Bool) {
        var parser = parser
        switch parser.next() {
        case .incomplete:
            if endOfInput {
                connection.cancel()
            } else {
                receive(into: parser)
            }

        case .request(let request):
            let response = router.respond(to: request)
            let keepAlive = request.keepAlive && !endOfInput
            let remaining = parser
            send(response, keepAlive: keepAlive, includeBody: request.method != "HEAD") {
                if keepAlive {
                    process(remaining, endOfInput: false)
                }
            }

        case .failure(let status):
            send(.error(status), keepAlive: false) {}
        }
    }

    /// Sends the response; closes the connection afterwards unless `keepAlive`.
    private func send(
        _ response: HTTPResponse,
        keepAlive: Bool,
        includeBody: Bool = true,
        then next: @escaping @Sendable () -> Void
    ) {
        connection.send(
            content: response.serialized(keepAlive: keepAlive, includeBody: includeBody),
            contentContext: keepAlive ? .defaultMessage : .finalMessage,
            isComplete: true,
            completion: .contentProcessed { [connection] error in
                if error == nil, keepAlive {
                    next()
                } else {
                    connection.cancel()
                }
            }
        )
    }
}

import Foundation
import KVHTTP

func fail(_ message: String, code: Int32) -> Never {
    FileHandle.standardError.write(Data("kvhttp: \(message)\n".utf8))
    exit(code)
}

let arguments = CommandLine.arguments
guard arguments.count == 2, let port = Int(arguments[1]) else {
    fail("usage: \(arguments.first ?? "app") <port>", code: 64)
}

let server: Server
do {
    server = try Server(port: port)
} catch {
    fail("cannot start server: \(error)", code: 1)
}
server.start { error in
    fail("listener failed: \(error)", code: 1)
}
dispatchMain()

import Testing
@testable import KVHTTP

@Suite struct HTTPRequestParserTests {
    private func parser(_ text: String, maxBodyBytes: Int = 1024) -> HTTPRequestParser {
        var parser = HTTPRequestParser(maxBodyBytes: maxBodyBytes)
        parser.append(text.utf8)
        return parser
    }

    @Test func parsesRequestWithBodyAcrossChunks() {
        var parser = HTTPRequestParser(maxBodyBytes: 1024)
        parser.append("PUT /kv/a HTTP/1.1\r\nContent-Le".utf8)
        #expect(parser.next() == .incomplete)
        parser.append("ngth: 5\r\nConnection: close\r\n\r\nhel".utf8)
        #expect(parser.next() == .incomplete)
        parser.append("lo".utf8)
        guard case .request(let request) = parser.next() else {
            Issue.record("expected a request")
            return
        }
        #expect(request.method == "PUT")
        #expect(request.path == "/kv/a")
        #expect(request.body == Array("hello".utf8))
        #expect(!request.keepAlive)
    }

    @Test func handlesPipelinedRequests() {
        var parser = parser("GET /a HTTP/1.1\r\n\r\nGET /b HTTP/1.0\r\n\r\n")
        guard case .request(let first) = parser.next(), case .request(let second) = parser.next() else {
            Issue.record("expected two requests")
            return
        }
        #expect(first.path == "/a" && first.keepAlive)
        #expect(second.path == "/b" && !second.keepAlive)
        #expect(parser.next() == .incomplete)
    }

    @Test(arguments: [
        ("garbage\r\n\r\n", HTTPStatus.badRequest),
        ("GET / HTTP/2.0\r\n\r\n", .versionNotSupported),
        ("PUT /a HTTP/1.1\r\nContent-Length: x\r\n\r\n", .badRequest),
        ("PUT /a HTTP/1.1\r\nContent-Length: 1\r\nContent-Length: 2\r\n\r\n", .badRequest),
        ("PUT /a HTTP/1.1\r\nContent-Length: 2048\r\n\r\n", .payloadTooLarge),
        ("PUT /a HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n", .notImplemented),
    ])
    func rejectsInvalidRequests(text: String, status: HTTPStatus) {
        var parser = parser(text)
        #expect(parser.next() == .failure(status))
    }
}

import Testing
@testable import KVHTTP

@Suite struct RouterTests {
    let router = Router(store: KVStore())

    private func call(_ method: String, _ path: String, _ body: String = "") -> HTTPResponse {
        router.respond(to: HTTPRequest(method: method, path: path, body: Array(body.utf8)))
    }

    @Test func health() {
        let response = call("GET", "/health")
        #expect(response.status == .ok)
        #expect(response.body == Array("ok".utf8))
        #expect(call("POST", "/health").status == .methodNotAllowed)
    }

    @Test func crud() {
        #expect(call("PUT", "/kv/a", "hello").status == .created)
        #expect(call("GET", "/kv/a").body == Array("hello".utf8))
        #expect(call("PUT", "/kv/a", "world").status == .ok)
        #expect(call("DELETE", "/kv/a").status == .noContent)
        #expect(call("GET", "/kv/a").status == .notFound)
        #expect(call("DELETE", "/kv/a").status == .notFound)
    }

    @Test func listIsSortedJSON() {
        for key in ["b", "a", "C"] { _ = call("PUT", "/kv/\(key)", "x") }
        let response = call("GET", "/kv")
        #expect(response.contentType == "application/json")
        #expect(response.body == Array(#"["C","a","b"]"#.utf8))
        #expect(call("DELETE", "/kv").status == .methodNotAllowed)
    }

    @Test(arguments: ["/kv/", "/kv/a.b", "/kv/a/b", "/kv/" + String(repeating: "k", count: 65), "/kv/%41", "/kv/é"])
    func invalidKeys(path: String) {
        #expect(call("GET", path).status == .badRequest)
    }

    @Test func maxLengthKeyIsValid() {
        #expect(call("PUT", "/kv/" + String(repeating: "k", count: 64), "v").status == .created)
    }

    @Test func unknownPathsAndMethods() {
        #expect(call("GET", "/nope").status == .notFound)
        #expect(call("GET", "/kvx").status == .notFound)
        #expect(call("PATCH", "/kv/a").status == .methodNotAllowed)
    }
}
